//! IR -> generated artifacts: Mermaid/PlantUML diagrams and per-layer test
//! skeletons (pytest, rstest, Gherkin, Playwright, Rego, conftest,
//! import-linter, dependency-cruiser).
//!
//! Every artifact type is one pure function taking `&Workspace`. Rendering is
//! deterministic: regenerating without IR changes yields byte-identical files.

use std::collections::BTreeMap;

use decispec_ir::names;
use decispec_ir::{Flow, FlowStep, Layer, Spec, Workspace};

pub const HEADER_TEXT: &str =
    "GENERATED BY DECISIONSPEC v0.1 — DO NOT EDIT. Edit specs/*.spec instead.";

#[derive(Debug, Clone)]
pub struct CodegenConfig {
    /// `stack.lang` from decispec.toml: "python" (default) or "rust".
    pub lang: String,
    /// `stack.glue_module`: Python glue import path.
    pub glue_module: String,
    /// `stack.rust_glue`: Rust glue path referenced in `// glue:` comments.
    pub rust_glue: String,
    /// `stack.fitness.root_package`: python package the fitness linters are
    /// rooted at. Empty means "not configured", in which case `.importlinter`
    /// omits the setting rather than emitting an empty value that would make
    /// import-linter fail to parse the file.
    pub root_package: String,
    /// `[stack.fitness.packages]` container-id -> importable module path, so a
    /// model container named `api` can be checked as `myapp.api` instead of a
    /// bare `api` that no interpreter can resolve. Containers with no entry
    /// fall back to the container id (see `fitness_module`).
    pub container_packages: BTreeMap<String, String>,
}

impl Default for CodegenConfig {
    fn default() -> Self {
        CodegenConfig {
            lang: "python".to_string(),
            glue_module: "tests.glue".to_string(),
            rust_glue: "tests/glue/rust".to_string(),
            root_package: String::new(),
            container_packages: BTreeMap::new(),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct GeneratedFile {
    /// Project-relative path with forward slashes, e.g. `docs/diagrams/x.mmd`.
    pub path: String,
    pub content: String,
}

/// The generated-file header in the comment style appropriate for `path`.
pub fn header(path: &str) -> String {
    let ext = path.rsplit('.').next().unwrap_or("");
    let comment = match ext {
        "mmd" => "%%",
        "puml" => "'",
        "ts" | "cjs" | "rs" => "//",
        _ => "#",
    };
    format!("{comment} {HEADER_TEXT}\n")
}

fn file(path: String, body: String) -> GeneratedFile {
    let content = format!("{}{body}", header(&path));
    GeneratedFile { path, content }
}

// ---------------------------------------------------------------------------
// Diagrams
// ---------------------------------------------------------------------------

pub fn mermaid_flow(flow: &Flow) -> String {
    let mut out = String::from("sequenceDiagram\n");
    render_mermaid_steps(&flow.steps, 1, &mut out);
    out
}

fn render_mermaid_steps(steps: &[FlowStep], depth: usize, out: &mut String) {
    let indent = "    ".repeat(depth);
    for step in steps {
        match step {
            FlowStep::Message {
                from,
                to,
                label,
                dashed,
            } => {
                let arrow = if *dashed { "-->>" } else { "->>" };
                out.push_str(&format!("{indent}{from}{arrow}{to}: {label}\n"));
            }
            FlowStep::Alt {
                name,
                then_branch,
                else_branch,
            } => {
                out.push_str(&format!("{indent}alt {name}\n"));
                render_mermaid_steps(then_branch, depth + 1, out);
                out.push_str(&format!("{indent}else\n"));
                render_mermaid_steps(else_branch, depth + 1, out);
                out.push_str(&format!("{indent}end\n"));
            }
        }
    }
}

pub fn plantuml_flow(flow: &Flow) -> String {
    let mut out = String::from("@startuml\n");
    render_plantuml_steps(&flow.steps, 0, &mut out);
    out.push_str("@enduml\n");
    out
}

fn render_plantuml_steps(steps: &[FlowStep], depth: usize, out: &mut String) {
    let indent = "    ".repeat(depth);
    for step in steps {
        match step {
            FlowStep::Message {
                from,
                to,
                label,
                dashed,
            } => {
                let arrow = if *dashed { "-->" } else { "->" };
                out.push_str(&format!("{indent}{from} {arrow} {to} : {label}\n"));
            }
            FlowStep::Alt {
                name,
                then_branch,
                else_branch,
            } => {
                out.push_str(&format!("{indent}alt {name}\n"));
                render_plantuml_steps(then_branch, depth + 1, out);
                out.push_str(&format!("{indent}else\n"));
                render_plantuml_steps(else_branch, depth + 1, out);
                out.push_str(&format!("{indent}end\n"));
            }
        }
    }
}

/// Mermaid flowchart edge labels (`-->|label|`) cannot contain `(` or `)`
/// (a paren anywhere in one label is a diagram-wide syntax error — verified
/// against mermaid.ink) or `|` (terminates the label early). Render the
/// paren entities and a slash for the pipe; the IR keeps the raw strings.
fn mermaid_edge_label(label: &str) -> String {
    label
        .replace('|', "/")
        .replace('(', "&#40;")
        .replace(')', "&#41;")
}

pub fn mermaid_model(ws: &Workspace) -> String {
    let mut out = String::from("flowchart LR\n");
    for m in &ws.models {
        for c in &m.containers {
            out.push_str(&format!("    {}[\"{}\"]\n", c.id, c.label));
        }
    }
    for rel in ws.all_rels() {
        out.push_str(&format!(
            "    {} -->|{}| {}\n",
            rel.from,
            mermaid_edge_label(&rel.label),
            rel.to
        ));
    }
    out
}

pub fn plantuml_model(ws: &Workspace) -> String {
    let mut out = String::from("@startuml\nleft to right direction\n");
    for m in &ws.models {
        for c in &m.containers {
            out.push_str(&format!("[{}] as {}\n", c.label, c.id));
        }
    }
    for rel in ws.all_rels() {
        out.push_str(&format!("{} --> {} : {}\n", rel.from, rel.to, rel.label));
    }
    out.push_str("@enduml\n");
    out
}

// ---------------------------------------------------------------------------
// unit layer: pytest (+ optional rstest skeletons)
// ---------------------------------------------------------------------------

/// Insert the project root into sys.path so the glue package is importable
/// regardless of pytest's conftest/rootdir handling.
const PYTEST_PATH_BOOTSTRAP: &str = "\
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[3]))

";

pub fn pytest_scenario_test(spec: &Spec, scenario_id: &str, cfg: &CodegenConfig) -> GeneratedFile {
    let test_name = names::pytest_scenario_test_name(&spec.id, scenario_id);
    let then = spec
        .scenario(scenario_id)
        .map(|s| s.then.as_str())
        .unwrap_or("");
    let path = format!(
        "tests/generated/unit/{}",
        names::unit_test_file(&spec.id, scenario_id)
    );
    let body = format!(
        "{PYTEST_PATH_BOOTSTRAP}import pytest\n\nimport {glue} as glue\n\n\n\
         @pytest.mark.parametrize(\"layer\", [\"unit\"])\n\
         def {test_name}(layer):\n\
         \x20   \"\"\"Scenario {scenario_id} (spec {spec_id}): {then}\"\"\"\n\
         \x20   glue.{scenario_id}()\n",
        glue = cfg.glue_module,
        spec_id = spec.id,
    );
    file(path, body)
}

pub fn pytest_invariant_test(
    spec: &Spec,
    invariant: &decispec_ir::Invariant,
    cfg: &CodegenConfig,
) -> GeneratedFile {
    let test_name = names::pytest_invariant_test_name(&spec.id, &invariant.id);
    let path = format!(
        "tests/generated/unit/{}",
        names::invariant_test_file(&spec.id, &invariant.id)
    );
    let body = format!(
        "{PYTEST_PATH_BOOTSTRAP}import {glue} as glue\n\n\n\
         def {test_name}():\n\
         \x20   \"\"\"Invariant {inv_id} (spec {spec_id}):\n\n\
         \x20   {expr}\n\
         \x20   \"\"\"\n\
         \x20   glue.invariant_{inv_id}()\n",
        glue = cfg.glue_module,
        spec_id = spec.id,
        inv_id = invariant.id,
        expr = invariant.expr,
    );
    file(path, body)
}

pub fn rust_unit_skeleton(spec: &Spec, cfg: &CodegenConfig) -> GeneratedFile {
    let mut body = format!("// glue: {}\n\n", cfg.rust_glue);
    for scen in &spec.scenarios {
        if spec.layers_for_scenario(&scen.id).contains(&Layer::Unit) {
            body.push_str(&format!(
                "#[test]\nfn scenario_{}_unit() {{\n    todo!(\"implement per {}\")\n}}\n\n",
                names::sanitize(&scen.id),
                spec.id
            ));
        }
    }
    for inv in &spec.invariants {
        if inv.layers.contains(&Layer::Unit) {
            body.push_str(&format!(
                "#[test]\nfn invariant_{}_unit() {{\n    todo!(\"implement per {}\")\n}}\n\n",
                names::sanitize(&inv.id),
                spec.id
            ));
        }
    }
    let path = format!(
        "tests/generated/unit/rust/{}",
        names::rust_unit_file(&spec.id)
    );
    file(path, body)
}

// ---------------------------------------------------------------------------
// contract layer: Gherkin
// ---------------------------------------------------------------------------

pub fn gherkin_feature(ws: &Workspace, spec: &Spec) -> GeneratedFile {
    let decision = ws.decision(&spec.id);
    let feature_name = decision.map(|d| d.title.as_str()).unwrap_or(&spec.id);
    let mut body = format!("Feature: {feature_name}\n");
    for scen in &spec.scenarios {
        if spec
            .layers_for_scenario(&scen.id)
            .contains(&Layer::Contract)
        {
            body.push_str(&format!(
                "\n  Scenario: {id}\n    Given {given}\n    When {when}\n    Then {then}\n",
                id = names::contract_scenario_test_name(&spec.id, &scen.id),
                given = scen.given,
                when = scen.when,
                then = scen.then
            ));
        }
    }
    let path = format!(
        "tests/generated/contract/{}",
        names::contract_feature_file(&spec.id)
    );
    file(path, body)
}

// ---------------------------------------------------------------------------
// e2e layer: Playwright
// ---------------------------------------------------------------------------

pub fn playwright_spec(spec: &Spec, scenario: &decispec_ir::Scenario) -> GeneratedFile {
    let path = format!("tests/generated/e2e/{}", names::e2e_spec_file(&scenario.id));
    let body = format!(
        "import {{ test, expect }} from '@playwright/test';\n\n\
         test('{spec_id} {scen_id}', async ({{ page }}) => {{\n\
         \x20   // TODO per spec: {then}\n\
         }});\n",
        spec_id = spec.id,
        scen_id = scenario.id,
        then = scenario.then,
    );
    file(path, body)
}

// ---------------------------------------------------------------------------
// infra layer: Rego + conftest.toml
// ---------------------------------------------------------------------------

pub fn rego_policy(policy: &decispec_ir::InfraPolicy) -> GeneratedFile {
    let path = format!(
        "tests/generated/infra/{}",
        names::infra_policy_file(&policy.id)
    );
    let body = format!(
        "package decispec.{id}\n\n\
         # Policy \"{id}\": {description}\n\
         # TODO(decispec): implement the policy body. Example (no_hardcoded_secrets):\n\
         # flag any source/config file assigning a secret-looking literal, e.g.\n\
         #   regex.match(`(?i)(password|api_key|secret)\\s*=\\s*\"[^\"]+\"`, file_content)\n\
         deny[msg] {{\n\
         \x20   false\n\
         \x20   msg := \"{id}: <violation detail>\"\n\
         }}\n",
        id = policy.id,
        description = policy.description,
    );
    file(path, body)
}

pub fn conftest_toml() -> GeneratedFile {
    file(
        "tests/generated/infra/conftest.toml".to_string(),
        "[namespace]\n".to_string(),
    )
}

// ---------------------------------------------------------------------------
// fitness layer: import-linter + dependency-cruiser
// ---------------------------------------------------------------------------

/// Resolve the module path a fitness linter should use for `container`.
///
/// Configured containers map to their real importable package; unconfigured
/// ones fall back to the bare container id so codegen keeps producing a usable
/// (if incomplete) file. Returns `(module, is_configured)`.
///
/// Only the *module positions* of the emitted contract use this. Section names
/// and `name =` lines keep the raw container ids, so a contract's identity does
/// not change when someone edits `decispec.toml`.
fn fitness_module<'a>(cfg: &'a CodegenConfig, container: &'a str) -> (&'a str, bool) {
    match cfg.container_packages.get(container) {
        Some(pkg) => (pkg.as_str(), true),
        None => (container, false),
    }
}

pub fn importlinter(ws: &Workspace, cfg: &CodegenConfig) -> GeneratedFile {
    let mut body = String::from("[importlinter]\n");
    if cfg.root_package.is_empty() {
        body.push_str(
            "# TODO(decispec): set [stack.fitness] root_package in decispec.toml,\n\
             # e.g. root_package = mypkg\n",
        );
    } else {
        body.push_str(&format!("root_package = {}\n", cfg.root_package));
    }
    let mut unmapped: Vec<&str> = Vec::new();
    for rel in ws.all_rels() {
        let (from, from_ok) = fitness_module(cfg, &rel.from);
        let (to, to_ok) = fitness_module(cfg, &rel.to);
        if !from_ok {
            unmapped.push(&rel.from);
        }
        if !to_ok {
            unmapped.push(&rel.to);
        }
        body.push_str(&format!(
            "# rel {from} -> {to} : \"{label}\"\n\
             [contract:rel_{from}_{to}_forbidden]\n\
             name = rel {from} -> {to}: {to} must not import {from}\n\
             type = forbidden\n\
             source_modules =\n    {to_mod}\n\
             forbidden_modules =\n    {from_mod}\n\n\
             [contract:rel_{from}_{to}_allowed]\n\
             name = rel {from} -> {to}: {from} may import {to}\n\
             type = layers\n\
             layers =\n    {from_mod}\n    {to_mod}\n\n",
            from = rel.from,
            to = rel.to,
            from_mod = from,
            to_mod = to,
            label = rel.label,
        ));
    }
    unmapped.sort_unstable();
    unmapped.dedup();
    for c in unmapped {
        body.push_str(&format!(
            "# TODO(decispec): container '{c}' has no [stack.fitness.packages] entry; \
             using it verbatim as a module path\n"
        ));
    }
    file("tests/generated/fitness/.importlinter".to_string(), body)
}

/// dependency-cruiser matches **filesystem** paths in a JS/TS tree, where a
/// container id like `api` is a directory. `container_packages` holds python
/// dotted module paths, so applying it here would emit a regex that can never
/// match. It is deliberately config-independent for that reason.
pub fn depcruise(ws: &Workspace, _cfg: &CodegenConfig) -> GeneratedFile {
    let mut rules = String::new();
    for rel in ws.all_rels() {
        let from = &rel.from;
        let to = &rel.to;
        rules.push_str(&format!(
            "    // rel {from} -> {to} : \"{label}\" (forbid {to} -> {from})\n    {{\n      \
             name: 'decispec-{to}-not-{from}',\n      \
             comment: 'decispec rel {from} -> {to}: {to} must not import {from}',\n      \
severity: 'error',\n      \
             from: {{ path: '(^|[/\\\\]){from}([/\\\\]|$)' }},\n      \
             to: {{ path: '(^|[/\\\\]){to}([/\\\\]|$)' }},\n    }},\n",
            from = from,
            to = to,
            label = rel.label,
        ));
    }
    let body = format!(
        "/** @type {{import('dependency-cruiser').IConfiguration}} */\n\
         module.exports = {{\n  options: {{\n    doNotFollow: {{ path: 'node_modules' }},\n  }},\n  forbidden: [\n{rules}  ],\n}};\n"
    );
    file(
        "tests/generated/fitness/dependency-cruiser.cjs".to_string(),
        body,
    )
}

// ---------------------------------------------------------------------------
// Whole-workspace render
// ---------------------------------------------------------------------------

pub fn render_all(ws: &Workspace, cfg: &CodegenConfig) -> Vec<GeneratedFile> {
    let mut out: Vec<GeneratedFile> = Vec::new();

    // Diagrams: one sequence diagram per flow, one component diagram per model.
    for m in &ws.models {
        for flow in &m.flows {
            out.push(file(
                format!("docs/diagrams/{}.mmd", flow.id),
                mermaid_flow(flow),
            ));
            out.push(file(
                format!("docs/diagrams/{}.puml", flow.id),
                plantuml_flow(flow),
            ));
        }
    }
    let has_model = ws
        .models
        .iter()
        .any(|m| !m.containers.is_empty() || !m.rels.is_empty());
    if has_model {
        out.push(file(
            "docs/diagrams/model.mmd".to_string(),
            mermaid_model(ws),
        ));
        out.push(file(
            "docs/diagrams/model.puml".to_string(),
            plantuml_model(ws),
        ));
    }

    for spec in &ws.specs {
        // unit layer
        for scen in &spec.scenarios {
            if spec.layers_for_scenario(&scen.id).contains(&Layer::Unit) {
                out.push(pytest_scenario_test(spec, &scen.id, cfg));
            }
        }
        for inv in &spec.invariants {
            if inv.layers.contains(&Layer::Unit) {
                out.push(pytest_invariant_test(spec, inv, cfg));
            }
        }
        if cfg.lang == "rust"
            && (spec
                .scenarios
                .iter()
                .any(|s| spec.layers_for_scenario(&s.id).contains(&Layer::Unit))
                || spec
                    .invariants
                    .iter()
                    .any(|i| i.layers.contains(&Layer::Unit)))
        {
            out.push(rust_unit_skeleton(spec, cfg));
        }

        // contract layer
        if spec
            .scenarios
            .iter()
            .any(|s| spec.layers_for_scenario(&s.id).contains(&Layer::Contract))
        {
            out.push(gherkin_feature(ws, spec));
        }

        // e2e layer
        for scen in &spec.scenarios {
            if spec.layers_for_scenario(&scen.id).contains(&Layer::E2e) {
                out.push(playwright_spec(spec, scen));
            }
        }

        // infra layer
        for policy in &spec.infra_policies {
            if policy.layers.contains(&Layer::Infra) {
                out.push(rego_policy(policy));
            }
        }
    }
    if ws
        .specs
        .iter()
        .flat_map(|s| s.infra_policies.iter())
        .any(|p| p.layers.contains(&Layer::Infra))
    {
        out.push(conftest_toml());
    }

    // fitness layer
    if ws.all_rels().next().is_some() {
        out.push(importlinter(ws, cfg));
        out.push(depcruise(ws, cfg));
    }

    out
}

/// True when `content`'s first two lines carry the generated-file header for
/// `path`, exactly as written by [`header`].
pub fn has_generated_header(path: &str, content: &str) -> bool {
    let expected = header(path);
    content
        .lines()
        .take(2)
        .any(|line| line.trim_end() == expected.trim_end())
}

/// True for project-relative paths (forward slashes) that live in a tree
/// `decispec gen` manages: files directly under `docs/diagrams/`, or
/// anywhere under `tests/generated/<layer>/` for a known layer. Deliberately
/// conservative: `tests/generated/results/` (run manifests, written by
/// `decispec test`), files directly under `tests/generated/` and everything
/// under `tests/glue/` are never managed.
pub fn is_managed_path(rel: &str) -> bool {
    let parts: Vec<&str> = rel.split('/').collect();
    if let ["docs", "diagrams", file] = parts.as_slice() {
        return !file.is_empty();
    }
    if let ["tests", "generated", layer, rest @ ..] = parts.as_slice() {
        return !rest.is_empty() && Layer::ALL.iter().any(|l| l.dir() == *layer);
    }
    false
}

