    #[test]
    fn generated_header_detection_matches_first_two_lines() {
        let ws = decispec_parse_for_tests::parse_demo();
        let generated = render_all(&ws, &CodegenConfig::default());
        assert!(!generated.is_empty());
        for f in &generated {
            assert!(
                has_generated_header(&f.path, &f.content),
                "{} should carry its header",
                f.path
            );
            let body_only = f.content.lines().skip(1).collect::<Vec<_>>().join("\n");
            assert!(
                !has_generated_header(&f.path, &body_only),
                "{0} without its first line must not count as generated",
                f.path
            );
        }
        // Hand-written lookalikes must not match, nor a header past line 2.
        assert!(!has_generated_header(
            "tests/generated/unit/x.py",
            "# hand-written\n"
        ));
        let late_header = format!("#!\n\n{}", header("tests/generated/unit/x.py"));
        assert!(!has_generated_header(
            "tests/generated/unit/x.py",
            &late_header
        ));
    }
